import{_ as t,o as a,c as l,a8 as o}from"./chunks/framework.DB1tY2mn.js";const g=JSON.parse('{"title":"Untitled object in Mermaid Config Schema","description":"","frontmatter":{"editLink":"https://github.com/mermaid-js/mermaid/edit/develop/packages/mermaid/src/schemas/config.schema.yaml","head":[["link",{"rel":"canonical","href":"https://mermaid.ai/open-source/config/schema-docs/config-properties-elk.html"}]]},"headers":[],"relativePath":"config/schema-docs/config-properties-elk.md","filePath":"config/schema-docs/config-properties-elk.md"}'),i={name:"config/schema-docs/config-properties-elk.md"};function n(r,e,s,d,p,c){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="untitled-object-in-mermaid-config-schema" tabindex="-1">Untitled object in Mermaid Config Schema <a class="header-anchor" href="#untitled-object-in-mermaid-config-schema" aria-label="Permalink to &quot;Untitled object in Mermaid Config Schema&quot;">​</a></h1><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mermaid.js.org/schemas/config.schema.json#/properties/elk</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Abstract</th><th style="text-align:left;">Extensible</th><th style="text-align:left;">Status</th><th style="text-align:left;">Identifiable</th><th style="text-align:left;">Custom Properties</th><th style="text-align:left;">Additional Properties</th><th style="text-align:left;">Access Restrictions</th><th style="text-align:left;">Defined In</th></tr></thead><tbody><tr><td style="text-align:left;">Can be instantiated</td><td style="text-align:left;">No</td><td style="text-align:left;">Unknown status</td><td style="text-align:left;">No</td><td style="text-align:left;">Forbidden</td><td style="text-align:left;">Allowed</td><td style="text-align:left;">none</td><td style="text-align:left;"><a href="/dochub/mermaid/schemas/config.schema.json" title="open original schema">config.schema.json*</a></td></tr></tbody></table><h2 id="elk-type" tabindex="-1">elk Type <a class="header-anchor" href="#elk-type" aria-label="Permalink to &quot;elk Type&quot;">​</a></h2><p><code>object</code> (<a href="./config-properties-elk.html">Details</a>)</p><h1 id="elk-properties" tabindex="-1">elk Properties <a class="header-anchor" href="#elk-properties" aria-label="Permalink to &quot;elk Properties&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Property</th><th style="text-align:left;">Type</th><th style="text-align:left;">Required</th><th style="text-align:left;">Nullable</th><th style="text-align:left;">Defined by</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="#mergeedges">mergeEdges</a></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-mergeedges.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/mergeEdges">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#nodeplacementstrategy">nodePlacementStrategy</a></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-nodeplacementstrategy.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/nodePlacementStrategy">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#nodeplacementalignment">nodePlacementAlignment</a></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-nodeplacementalignment.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/nodePlacementAlignment">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#preset">preset</a></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-preset.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/preset">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#straightenedges">straightenEdges</a></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-straightenedges.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/straightenEdges">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#linehops">lineHops</a></td><td style="text-align:left;">Merged</td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-linehops.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/lineHops">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#layeringstrategy">layeringStrategy</a></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-layeringstrategy.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/layeringStrategy">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#layeringlayerbound">layeringLayerBound</a></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-layeringlayerbound.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/layeringLayerBound">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#cyclebreakingstrategy">cycleBreakingStrategy</a></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-cyclebreakingstrategy.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/cycleBreakingStrategy">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#forcenodemodelorder">forceNodeModelOrder</a></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-forcenodemodelorder.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/forceNodeModelOrder">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#considermodelorder">considerModelOrder</a></td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-considermodelorder.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/considerModelOrder">Mermaid Config</a></td></tr><tr><td style="text-align:left;"><a href="#keepentrynodeontop">keepEntryNodeOnTop</a></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">Optional</td><td style="text-align:left;">cannot be null</td><td style="text-align:left;"><a href="./config-properties-elk-properties-keepentrynodeontop.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/keepEntryNodeOnTop">Mermaid Config</a></td></tr></tbody></table><h2 id="mergeedges" tabindex="-1">mergeEdges <a class="header-anchor" href="#mergeedges" aria-label="Permalink to &quot;mergeEdges&quot;">​</a></h2><p>Elk specific option that allows edges to share path where it convenient. It can make for pretty diagrams but can also make it harder to read the diagram.</p><p><code>mergeEdges</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>boolean</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-mergeedges.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/mergeEdges">Mermaid Config</a></p></li></ul><h3 id="mergeedges-type" tabindex="-1">mergeEdges Type <a class="header-anchor" href="#mergeedges-type" aria-label="Permalink to &quot;mergeEdges Type&quot;">​</a></h3><p><code>boolean</code></p><h3 id="mergeedges-default-value" tabindex="-1">mergeEdges Default Value <a class="header-anchor" href="#mergeedges-default-value" aria-label="Permalink to &quot;mergeEdges Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="nodeplacementstrategy" tabindex="-1">nodePlacementStrategy <a class="header-anchor" href="#nodeplacementstrategy" aria-label="Permalink to &quot;nodePlacementStrategy&quot;">​</a></h2><p>Elk specific option affecting how nodes are placed.</p><p><code>nodePlacementStrategy</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>string</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-nodeplacementstrategy.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/nodePlacementStrategy">Mermaid Config</a></p></li></ul><h3 id="nodeplacementstrategy-type" tabindex="-1">nodePlacementStrategy Type <a class="header-anchor" href="#nodeplacementstrategy-type" aria-label="Permalink to &quot;nodePlacementStrategy Type&quot;">​</a></h3><p><code>string</code></p><h3 id="nodeplacementstrategy-constraints" tabindex="-1">nodePlacementStrategy Constraints <a class="header-anchor" href="#nodeplacementstrategy-constraints" aria-label="Permalink to &quot;nodePlacementStrategy Constraints&quot;">​</a></h3><p><strong>enum</strong>: the value of this property must be equal to one of the following values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;SIMPLE&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;NETWORK_SIMPLEX&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;LINEAR_SEGMENTS&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;BRANDES_KOEPF&quot;</code></td><td style="text-align:left;"></td></tr></tbody></table><h2 id="nodeplacementalignment" tabindex="-1">nodePlacementAlignment <a class="header-anchor" href="#nodeplacementalignment" aria-label="Permalink to &quot;nodePlacementAlignment&quot;">​</a></h2><p>Elk specific option affecting Brandes-Koepf node placement alignment. NONE picks the alignment with the smallest height.</p><p><code>nodePlacementAlignment</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>string</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-nodeplacementalignment.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/nodePlacementAlignment">Mermaid Config</a></p></li></ul><h3 id="nodeplacementalignment-type" tabindex="-1">nodePlacementAlignment Type <a class="header-anchor" href="#nodeplacementalignment-type" aria-label="Permalink to &quot;nodePlacementAlignment Type&quot;">​</a></h3><p><code>string</code></p><h3 id="nodeplacementalignment-constraints" tabindex="-1">nodePlacementAlignment Constraints <a class="header-anchor" href="#nodeplacementalignment-constraints" aria-label="Permalink to &quot;nodePlacementAlignment Constraints&quot;">​</a></h3><p><strong>enum</strong>: the value of this property must be equal to one of the following values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;NONE&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;LEFTUP&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;LEFTDOWN&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;RIGHTUP&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;RIGHTDOWN&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;BALANCED&quot;</code></td><td style="text-align:left;"></td></tr></tbody></table><h3 id="nodeplacementalignment-default-value" tabindex="-1">nodePlacementAlignment Default Value <a class="header-anchor" href="#nodeplacementalignment-default-value" aria-label="Permalink to &quot;nodePlacementAlignment Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NONE&quot;</span></span></code></pre></div><h2 id="preset" tabindex="-1">preset <a class="header-anchor" href="#preset" aria-label="Permalink to &quot;preset&quot;">​</a></h2><p>Named combination of the three options that decide where nodes end up: layering strategy, node placement strategy and cycle breaking strategy. They belong to different phases of the layout, so a preset is simply a named triple rather than a mode with behaviour of its own.</p><p><code>default</code> — network simplex layering and placement with depth-first cycle breaking at the top level, and Brandes-Koepf placement inside subgraphs. Depth-first breaking gives shorter back edges on graphs that loop.</p><p><code>legacy</code> — what shipped before presets existed: Brandes-Koepf placement, which straightens long edges at the cost of that alignment, with ELK&#39;s own greedy cycle breaking. Reproduces the rendering of earlier versions rather than the defaults their schema advertised.</p><p><code>modelOrder</code> — as <code>default</code>, but breaks cycles by greedy model order, which disturbs declaration order least at the cost of longer back edges. This is the combination <code>default</code> named previously.</p><p><code>depthFirst</code> — a name for what <code>default</code> already is, for diagrams that would rather say depth-first than rely on the default.</p><p>Setting <code>layeringStrategy</code>, <code>nodePlacementStrategy</code> or <code>cycleBreakingStrategy</code> explicitly overrides the preset for that one option; the rest of the preset still applies.</p><p><code>preset</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>string</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-preset.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/preset">Mermaid Config</a></p></li></ul><h3 id="preset-type" tabindex="-1">preset Type <a class="header-anchor" href="#preset-type" aria-label="Permalink to &quot;preset Type&quot;">​</a></h3><p><code>string</code></p><h3 id="preset-constraints" tabindex="-1">preset Constraints <a class="header-anchor" href="#preset-constraints" aria-label="Permalink to &quot;preset Constraints&quot;">​</a></h3><p><strong>enum</strong>: the value of this property must be equal to one of the following values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;default&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;legacy&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;modelOrder&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;depthFirst&quot;</code></td><td style="text-align:left;"></td></tr></tbody></table><h3 id="preset-default-value" tabindex="-1">preset Default Value <a class="header-anchor" href="#preset-default-value" aria-label="Permalink to &quot;preset Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span></span></code></pre></div><h2 id="straightenedges" tabindex="-1">straightenEdges <a class="header-anchor" href="#straightenedges" aria-label="Permalink to &quot;straightenEdges&quot;">​</a></h2><p>Straightens an edge that leaves or enters a node with a tiny step.</p><p>ELK spreads an edge&#39;s port evenly along a node&#39;s side but routes the edge down a channel whose row rarely lines up with that port exactly, leaving a staircase of a few pixels right at the border. With rounded corners the two micro-bends land on top of each other and read as a kink. Enabling this moves the channel onto the port&#39;s row and drops the step, so the edge draws as one straight line and both ports stay exactly where the layout put them.</p><p>Only the step next to a node is touched, and only when the edge continues the same way afterwards, so a real turn is never collapsed. An edge is left alone entirely when moving its run would drag the far port, or would introduce a crossing.</p><p><code>straightenEdges</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>boolean</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-straightenedges.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/straightenEdges">Mermaid Config</a></p></li></ul><h3 id="straightenedges-type" tabindex="-1">straightenEdges Type <a class="header-anchor" href="#straightenedges-type" aria-label="Permalink to &quot;straightenEdges Type&quot;">​</a></h3><p><code>boolean</code></p><h3 id="straightenedges-default-value" tabindex="-1">straightenEdges Default Value <a class="header-anchor" href="#straightenedges-default-value" aria-label="Permalink to &quot;straightenEdges Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h2 id="linehops" tabindex="-1">lineHops <a class="header-anchor" href="#linehops" aria-label="Permalink to &quot;lineHops&quot;">​</a></h2><p>Renders edge crossings as small arcs (&quot;hops&quot;) or visible gaps, so that it is clear which line passes over which where two edges meet.</p><p>The edge that gives way loses its corner rounding for the segment carrying the hop, which is the trade for a readable crossing. Curved edges are skipped rather than rewritten, to avoid corrupting their geometry. Set to <code>false</code> to draw plain crossings.</p><p><code>lineHops</code></p><ul><li><p>is optional</p></li><li><p>Type: merged type (<a href="./config-properties-elk-properties-linehops.html">Details</a>)</p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-linehops.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/lineHops">Mermaid Config</a></p></li></ul><h3 id="linehops-type" tabindex="-1">lineHops Type <a class="header-anchor" href="#linehops-type" aria-label="Permalink to &quot;lineHops Type&quot;">​</a></h3><p>merged type (<a href="./config-properties-elk-properties-linehops.html">Details</a>)</p><p>one (and only one) of</p><ul><li><p><a href="./config-properties-elk-properties-linehops-oneof-0.html" title="check type definition">Untitled boolean in Mermaid Config</a></p></li><li><p><a href="./config-properties-elk-properties-linehops-oneof-1.html" title="check type definition">Untitled string in Mermaid Config</a></p></li></ul><h3 id="linehops-default-value" tabindex="-1">lineHops Default Value <a class="header-anchor" href="#linehops-default-value" aria-label="Permalink to &quot;lineHops Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h2 id="layeringstrategy" tabindex="-1">layeringStrategy <a class="header-anchor" href="#layeringstrategy" aria-label="Permalink to &quot;layeringStrategy&quot;">​</a></h2><p>Elk specific option deciding which layer each node is assigned to — the column in a left-to-right diagram, the row in a top-down one. This is the coarsest of the three placement decisions, so changing it moves nodes further than anything else short of altering spacing.</p><p>NETWORK_SIMPLEX aims for the fewest long edges. LONGEST_PATH pushes every node as late as it can go. COFFMAN_GRAHAM bounds how many nodes share a layer, giving a more even, block-like shape on wide graphs. MIN_WIDTH and STRETCH_WIDTH trade edge length for a narrower or wider drawing. INTERACTIVE honours positions already on the nodes.</p><p><code>layeringStrategy</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>string</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-layeringstrategy.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/layeringStrategy">Mermaid Config</a></p></li></ul><h3 id="layeringstrategy-type" tabindex="-1">layeringStrategy Type <a class="header-anchor" href="#layeringstrategy-type" aria-label="Permalink to &quot;layeringStrategy Type&quot;">​</a></h3><p><code>string</code></p><h3 id="layeringstrategy-constraints" tabindex="-1">layeringStrategy Constraints <a class="header-anchor" href="#layeringstrategy-constraints" aria-label="Permalink to &quot;layeringStrategy Constraints&quot;">​</a></h3><p><strong>enum</strong>: the value of this property must be equal to one of the following values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;NETWORK_SIMPLEX&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;LONGEST_PATH&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;LONGEST_PATH_SOURCE&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;COFFMAN_GRAHAM&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;MIN_WIDTH&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;STRETCH_WIDTH&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;INTERACTIVE&quot;</code></td><td style="text-align:left;"></td></tr></tbody></table><h2 id="layeringlayerbound" tabindex="-1">layeringLayerBound <a class="header-anchor" href="#layeringlayerbound" aria-label="Permalink to &quot;layeringLayerBound&quot;">​</a></h2><p>Elk specific option capping how many nodes COFFMAN_GRAHAM will put in one layer. Ignored by every other layering strategy. Lower values give a taller, narrower drawing.</p><p><code>layeringLayerBound</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>number</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-layeringlayerbound.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/layeringLayerBound">Mermaid Config</a></p></li></ul><h3 id="layeringlayerbound-type" tabindex="-1">layeringLayerBound Type <a class="header-anchor" href="#layeringlayerbound-type" aria-label="Permalink to &quot;layeringLayerBound Type&quot;">​</a></h3><p><code>number</code></p><h3 id="layeringlayerbound-default-value" tabindex="-1">layeringLayerBound Default Value <a class="header-anchor" href="#layeringlayerbound-default-value" aria-label="Permalink to &quot;layeringLayerBound Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span></span></code></pre></div><h2 id="cyclebreakingstrategy" tabindex="-1">cycleBreakingStrategy <a class="header-anchor" href="#cyclebreakingstrategy" aria-label="Permalink to &quot;cycleBreakingStrategy&quot;">​</a></h2><p>This strategy decides how to find cycles in the graph and deciding which edges need adjustment to break loops.</p><p><code>cycleBreakingStrategy</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>string</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-cyclebreakingstrategy.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/cycleBreakingStrategy">Mermaid Config</a></p></li></ul><h3 id="cyclebreakingstrategy-type" tabindex="-1">cycleBreakingStrategy Type <a class="header-anchor" href="#cyclebreakingstrategy-type" aria-label="Permalink to &quot;cycleBreakingStrategy Type&quot;">​</a></h3><p><code>string</code></p><h3 id="cyclebreakingstrategy-constraints" tabindex="-1">cycleBreakingStrategy Constraints <a class="header-anchor" href="#cyclebreakingstrategy-constraints" aria-label="Permalink to &quot;cycleBreakingStrategy Constraints&quot;">​</a></h3><p><strong>enum</strong>: the value of this property must be equal to one of the following values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;GREEDY&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;DEPTH_FIRST&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;INTERACTIVE&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;MODEL_ORDER&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;GREEDY_MODEL_ORDER&quot;</code></td><td style="text-align:left;"></td></tr></tbody></table><h2 id="forcenodemodelorder" tabindex="-1">forceNodeModelOrder <a class="header-anchor" href="#forcenodemodelorder" aria-label="Permalink to &quot;forceNodeModelOrder&quot;">​</a></h2><p>The node order given by the model does not change to produce a better layout. E.g. if node A is before node B in the model this is not changed during crossing minimization. This assumes that the node model order is already respected before crossing minimization. This can be achieved by setting considerModelOrder.strategy to NODES_AND_EDGES.</p><p><code>forceNodeModelOrder</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>boolean</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-forcenodemodelorder.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/forceNodeModelOrder">Mermaid Config</a></p></li></ul><h3 id="forcenodemodelorder-type" tabindex="-1">forceNodeModelOrder Type <a class="header-anchor" href="#forcenodemodelorder-type" aria-label="Permalink to &quot;forceNodeModelOrder Type&quot;">​</a></h3><p><code>boolean</code></p><h3 id="forcenodemodelorder-default-value" tabindex="-1">forceNodeModelOrder Default Value <a class="header-anchor" href="#forcenodemodelorder-default-value" aria-label="Permalink to &quot;forceNodeModelOrder Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="considermodelorder" tabindex="-1">considerModelOrder <a class="header-anchor" href="#considermodelorder" aria-label="Permalink to &quot;considerModelOrder&quot;">​</a></h2><p>Preserves the order of nodes and edges in the model file if this does not lead to additional edge crossings. Depending on the strategy this is not always possible since the node and edge order might be conflicting.</p><p><code>considerModelOrder</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>string</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-considermodelorder.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/considerModelOrder">Mermaid Config</a></p></li></ul><h3 id="considermodelorder-type" tabindex="-1">considerModelOrder Type <a class="header-anchor" href="#considermodelorder-type" aria-label="Permalink to &quot;considerModelOrder Type&quot;">​</a></h3><p><code>string</code></p><h3 id="considermodelorder-constraints" tabindex="-1">considerModelOrder Constraints <a class="header-anchor" href="#considermodelorder-constraints" aria-label="Permalink to &quot;considerModelOrder Constraints&quot;">​</a></h3><p><strong>enum</strong>: the value of this property must be equal to one of the following values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;NONE&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;NODES_AND_EDGES&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;PREFER_EDGES&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;PREFER_NODES&quot;</code></td><td style="text-align:left;"></td></tr></tbody></table><h3 id="considermodelorder-default-value" tabindex="-1">considerModelOrder Default Value <a class="header-anchor" href="#considermodelorder-default-value" aria-label="Permalink to &quot;considerModelOrder Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NODES_AND_EDGES&quot;</span></span></code></pre></div><h2 id="keepentrynodeontop" tabindex="-1">keepEntryNodeOnTop <a class="header-anchor" href="#keepentrynodeontop" aria-label="Permalink to &quot;keepEntryNodeOnTop&quot;">​</a></h2><p>Elk specific option that keeps the entry node of a recursive flow at the top of the layout.</p><p>When a flow loops back on itself (a back-edge to an earlier node), ELK&#39;s degree-based cycle-breaking has no notion of an &quot;entry point&quot; and may rank the first-declared node in the middle, scrambling the reading order. When enabled, the entry node of each cyclic component is pinned to the first layer so the diagram still reads from its entry. Acyclic flows always have a natural source, so this has no effect on them.</p><p>Only applies when the cyclic flow has no node without incoming edges: if the loop is fed from outside (e.g. a start node pointing into it), that component already has a natural source and nothing is pinned. Detection is also scoped per container, so cycles that cross a subgraph boundary are not detected.</p><p><code>keepEntryNodeOnTop</code></p><ul><li><p>is optional</p></li><li><p>Type: <code>boolean</code></p></li><li><p>cannot be null</p></li><li><p>defined in: <a href="./config-properties-elk-properties-keepentrynodeontop.html" title="https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/keepEntryNodeOnTop">Mermaid Config</a></p></li></ul><h3 id="keepentrynodeontop-type" tabindex="-1">keepEntryNodeOnTop Type <a class="header-anchor" href="#keepentrynodeontop-type" aria-label="Permalink to &quot;keepEntryNodeOnTop Type&quot;">​</a></h3><p><code>boolean</code></p><h3 id="keepentrynodeontop-default-value" tabindex="-1">keepEntryNodeOnTop Default Value <a class="header-anchor" href="#keepentrynodeontop-default-value" aria-label="Permalink to &quot;keepEntryNodeOnTop Default Value&quot;">​</a></h3><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div>',137)])])}const f=t(i,[["render",n]]);export{g as __pageData,f as default};
